def parser(log: str) -> dict[str, str]:
    import re

    result: dict[str, str] = {}
    status_re = re.compile(
        r"^(?P<test>(?:\S+::\S+(?:\[[^\]]+\])?|\S+\.py))\s+"
        r"(?P<status>PASSED|FAILED|ERROR|SKIPPED|XFAIL|XPASS)\b"
    )
    summary_re = re.compile(
        r"^(?P<status>PASSED|FAILED|ERROR|SKIPPED|XFAIL|XPASS)\s+"
        r"(?P<test>(?:\S+::\S+(?:\[[^\]]+\])?|\S+\.py))\b"
    )
    not_found_re = re.compile(
        r"^ERROR:\s+not found:\s+(?P<test>\S+)"
    )

    for raw_line in log.splitlines():
        line = raw_line.strip()
        match = status_re.search(line) or summary_re.search(line)
        if not match:
            missing = not_found_re.search(line)
            if not missing:
                continue
            test = missing.group("test")
            # Keep parser conservative: only accept clear pytest-like test IDs.
            if "::" in test or test.endswith(".py"):
                result[test] = "fail"
            continue
        status = match.group("status").upper()
        test = match.group("test")
        if status == "PASSED":
            result[test] = "pass"
        elif status == "SKIPPED":
            result[test] = "skip"
        else:
            result[test] = "fail"
    return result

