            test = missing.group("test")
            # Keep parser conservative: only accept clear pytest-like test IDs.
            if "::" in test or test.endswith(".py"):
                result[test] = "fail"
            continue
        status = match.group("status").upper()
        test = match.group("test")
        if status == "PASSED":
            result[test] = "pass"
        elif status == "SKIPPED":
            result[test] = "skip"
        else:
            result[test] = "fail"
    return result

